  'help.faq.cantLogin.q': 'نمی‌توانم به حسابم دسترسی پیدا کنم',
  'help.faq.cantLogin.a': 'بررسی کن که آیا از ایمیل و رمز عبور درست استفاده می‌کنی. اگر رمز عبور را فراموش کردی، روی "رمز عبور را فراموش کرده‌ام؟" در صفحه ورود کلیک کن. اگر مشکل ادامه داشت، یک تیکت پشتیبانی بساز.',
