  'help.faq.accountSecurity.q': 'فکر می‌کنم حسابم به خطر افتاده',
  'help.faq.accountSecurity.a': 'فوری رمز عبورت را تغییر بده. پوشه ارسال شده‌ها را برای پیام‌هایی که ارسال نکرده‌ای بررسی کن. احراز هویت دو مرحله‌ای را در تنظیمات > امنیت فعال کن. اگر لازم بود، یک تیکت فوری بساز.',
  'help.faq.appAccess.q': 'چطور به اپلیکیشن در موبایل دسترسی پیدا کنم؟',
  'help.faq.appAccess.a': 'می‌توانی از طریق مرورگر به Chatyy در chatyy.com.br دسترسی پیدا کنی، یا اپ ما را از فروشگاه اپلیکیشن دستگاهت دانلود کنی.',
  'privacy.title': 'سیاست حفظ حریم خصوصی',
  'privacy.subtitle': 'چطور داده‌های شما را محافظت و مدیریت می‌کنیم',
  'privacy.lastUpdated': 'آخرین به‌روزرسانی: مارس ۲۰۲۶',
  'privacy.dataCollection.title': 'جمع‌آوری داده‌ها',
  'privacy.dataCollection.body': 'فقط اطلاعات لازم برای خدمات ایمیل را جمع‌آوری می‌کنیم: نام شما، آدرس ایمیل و محتوای پیام‌های ارسال و دریافت شده. داده‌های شخصی شما را به هیچ‌کس برای اهداف بازاریابی نمی‌فروشیم یا به اشتراک نمی‌گذاریم.',
  'privacy.dataUsage.title': 'چطور از داده‌های شما استفاده می‌کنیم',
  'privacy.dataUsage.body': 'داده‌های شما به‌طور انحصاری برای راه‌اندازی و بهبود خدمات ایمیل، از جمله تحویل پیام‌ها، فیلتر کردن اسپم، ویژگی‌های هوش مصنوعی (با رضایت شما) و امنیت حساب استفاده می‌شود.',
  'privacy.dataSecurity.title': 'امنیت داده‌ها',
  'privacy.dataSecurity.body': 'برای همه داده‌ها در حال انتقال و در حالت استراحت از رمزنگاری استاندارد صنعتی (TLS/SSL) استفاده می‌کنیم. جلسات با توکن‌های رمزنگاری شده و حفاظت CSRF محافظت می‌شوند. به‌طور منظم شیوه‌های امنیتی خود را بررسی می‌کنیم.',
  'privacy.cookies.title': 'کوکی‌ها و ذخیره‌سازی محلی',
  'privacy.cookies.body': 'ما از کوکی‌های ضروری و ذخیره‌سازی محلی برای حفظ جلسه شما، به خاطر سپردن ترجیحات شما (تم، زبان) و ارائه تجربه‌ای روان استفاده می‌کنیم. از کوکی‌های ردیابی شخص ثالث استفاده نمی‌کنیم.',
  'privacy.thirdParties.title': 'خدمات شخص ثالث',
  'privacy.thirdParties.body': 'ممکن است از خدمات شخص ثالث برای ویژگی‌های خاص مانند هوش مصنوعی (Anthropic Claude) و اعلان‌های فشاری استفاده کنیم. این خدمات سیاست‌های حفظ حریم خصوصی خود را دارند و فقط حداقل داده‌های لازم را پردازش می‌کنند.',
  'privacy.rights.title': 'حقوق شما',
  'privacy.rights.body': 'شما حق دسترسی، اصلاح، صادرات یا حذف داده‌های شخصی خود را در هر زمان دارید. می‌توانید داده‌های خود را در تنظیمات مدیریت کنید یا با پشتیبانی ما تماس بگیرید.',
  'privacy.contact.title': 'با ما تماس بگیرید',
  'privacy.contact.body': 'برای مسائل مربوط به حریم خصوصی یا درخواست‌های داده، از طریق privacy@chatyy.com.br با ما تماس بگیرید. در عرض ۳۰ روز پاسخ خواهیم داد.',
  'terms.title': 'شرایط خدمات',
  'terms.subtitle': 'راهنماهای استفاده از Chatyy',
  'terms.lastUpdated': 'آخرین به‌روزرسانی: مارس ۲۰۲۶',
  'terms.acceptance.title': 'پذیرش شرایط',
  'terms.acceptance.body': 'با دسترسی یا استفاده از Chatyy، با این شرایط خدمات موافقت می‌کنی. اگر با هر بخشی از این شرایط موافق نیستی، از خدمات استفاده نکن.',
  'terms.services.title': 'توضیحات خدمات',
  'terms.services.body': 'Chatyy خدمات ارتباطی از طریق ایمیل شامل ارسال، دریافت و مدیریت ایمیل‌ها، به‌علاوه ویژگی‌های هوش مصنوعی، ادغام با تقویم و ویدئوکنفرانس را ارائه می‌دهد.',
  'terms.accounts.title': 'حساب‌های کاربری',
  'terms.accounts.body': 'شما مسئول حفظ امنیت اعتبارنامه‌های خود هستید. رمز عبور خود را به اشتراک نگذارید و اجازه دسترسی غیرمجاز به حساب خود را ندهید. برای استفاده از این خدمات باید حداقل ۱۳ سال داشته باشید.',
  'terms.conduct.title': 'استفاده قابل قبول',
  'terms.conduct.body': 'شما موافقت می‌کنید که از خدمات برای ارسال اسپم، بدافزار، فیشینگ یا هر محتوای غیرقانونی استفاده نکنید. سعی نکنید به حساب‌های دیگر کاربران دسترسی پیدا کنید یا زیرساخت خدمات را مختل کنید.',
  'terms.content.title': 'مالکیت محتوا',
  'terms.content.body': 'شما مالک تمام محتوایی هستید که ایجاد و از طریق خدمات ارسال می‌کنید. ما ادعای مالکیت بر ایمیل‌ها یا پیوست‌های شما نداریم. ممکن است محتوای شما را به‌طور لازم پردازش کنیم تا خدمات را ارائه دهیم.',
  'terms.limitation.title': 'محدودیت مسئولیت',
  'terms.limitation.body': 'Chatyy به‌صورت "همان‌طور که هست" ارائه می‌شود. ما به دنبال ۹۹.۹٪ در دسترس بودن هستیم اما خدمات مداوم را تضمین نمی‌کنیم. ما مسئول خسارات غیرمستقیم، تصادفی یا تبعی ناشی از استفاده از خدمات نیستیم.',
  'terms.termination.title': 'اختتام حساب',
  'terms.termination.body': 'ما می‌توانیم حساب‌هایی را که این شرایط را نقض می‌کنند، معلق یا خاتمه دهیم. شما می‌توانید هر زمان که بخواهید حساب خود را در تنظیمات حذف ک��ید. پس از خاتمه، داده‌های شما در عرض ۳۰ روز حذف خواهند شد.',
  'terms.changes.title': 'تغییرات در شرایط',
  'terms.changes.body': 'ما ممکن است این شرایط را به‌طور دوره‌ای به‌روزرسانی کنیم. در مورد تغییرات مهم از طریق ایمیل یا اعلان در اپ به شما اطلاع خواهیم داد. استفاده مداوم پس از تغییرات به معنای پذیرش شرایط به‌روزرسانی شده است.',
