  'plans.faqWhatIsPlus': 'Chatyy One چیست؟',
  'plans.faqWhatIsPlusAnswer': 'این پلن پریمیوم Chatyy است که همه مکالمات، عکس‌ها و ویدیوهای شما را محافظت می‌کند. با Chatyy One، حتی اگر چیزی را به‌طور ناخواسته حذف کنید، می‌توانید تا 30 روز آن را بازیابی کنید. علاوه بر این، 200 گیگابایت فضای ذخیره‌سازی، One AI به عنوان دستیار شخصی و امکان ارسال فایل‌های تا 100 مگابایت را دریافت می‌کنید.',
  'plans.faqCancelAnswer': 'پلن شما تا پایان دوره پرداخت فعال باقی می‌ماند. بعد از آن، به پلن رایگان برمی‌گردید. عکس‌ها و ویدیوهای شما که بیش از 15 گیگابایت باشد، به مدت 30 روز دیگر نگه‌داری می‌شود تا بتوانید دانلود کنید.',
  'plans.faqHowFamily': 'پلن پرو چگونه کار می‌کند؟',
  'plans.faqHowFamilyAnswer': 'شما می‌توانید تا 4 نفر از خانواده‌تان را اضافه کنید. همه 500 گیگابایت فضای ذخیره‌سازی را به اشتراک می‌گذارند و از همه مزایای Chatyy One بهره‌مند می‌شوند. هر نفر فضای خصوصی خود را دارد — هیچ‌کس فایل‌های دیگران را نمی‌بیند.',
  'plans.faqChangePlanAnswer': 'بله! اگر از Plus به Pro ارتقا دهید، فقط تفاوت متناسب شارژ می‌شود. اگر به پلن پایین‌تر بروید، پلن فعلی تا پایان دوره ادامه خواهد داشت.',
  'plans.faqCardDeclined': 'کارت من رد شد، چه کار کنم؟',
  'plans.faqCardDeclinedAnswer': 'شما 7 روز فرصت دارید تا کارت خود را به‌روز کنید. در این مدت، همه مزایای شما به کار خود ادامه می‌دهند. بعد از 7 روز، پلن به رایگان برمی‌گردد.',
  'plans.faqDataSafe': 'آیا داده‌های من امن هستند؟',
